actions.script:
def BD = { v -> (v ?: 0) as java.math.BigDecimal }
def half = { v -> BD(v).divide(new java.math.BigDecimal('2'), 2, java.math.RoundingMode.HALF_UP) }
def stateOf = { g -> (g && g.toString().length() >= 2) ? g.toString().substring(0,2) : null }
int y = Integer.parseInt(returnPeriod.substring(2)); int m = Integer.parseInt(returnPeriod.substring(0,2))
def fromD = java.sql.Date.valueOf(java.time.LocalDate.of(y, m, 1))
def toD = java.sql.Date.valueOf(java.time.LocalDate.of(y, m, 1).plusMonths(1))

def invoices = ec.entity.find('mantle.account.invoice.Invoice')
    .condition('toPartyId', organizationPartyId)
    .condition('invoiceTypeEnumId', 'in', ['InvoicePurchase','InvoicePurchaseReturn'])
    .condition('invoiceDate', '>=', new java.sql.Timestamp(fromD.time))
    .condition('invoiceDate', '<', new java.sql.Timestamp(toD.time))
    .condition('statusId', org.moqui.entity.EntityCondition.NOT_EQUAL, 'InvoiceCancelled').disableAuthz().list()

def tTaxable = BD(0), tIgst = BD(0), tCgst = BD(0), tSgst = BD(0), tCess = BD(0)
int matched = 0, unmatched = 0
def rows = []
def supState = null
def selfGstin = ec.entity.find('zenith.erp.india.IndiaGstin').condition('partyId', organizationPartyId).disableAuthz().one()
supState = selfGstin ? (selfGstin.stateCode ?: stateOf(selfGstin.gstin)) : null

invoices.each { inv ->
    def sign = (inv.invoiceTypeEnumId == 'InvoicePurchaseReturn') ? BD(-1) : BD(1)
    def taxable = BD(inv.totalTaxableAmount)
    def charged = BD(inv.invoiceTotal) - taxable
    if (charged.signum() < 0) charged = BD(0)
    def buyState = stateOf(inv.supplierGstin)     // supplier (vendor) state on a purchase
    boolean inter = (buyState != null && supState != null && buyState != supState) || (inv.isImportPurchase == 'Y')
    def iCgst = BD(0), iSgst = BD(0), iIgst = BD(0)
    if (inter) { iIgst = charged } else { iCgst = half(charged); iSgst = charged - iCgst }
    tTaxable += taxable * sign; tIgst += iIgst * sign; tCgst += iCgst * sign; tSgst += iSgst * sign

    def m2b = ec.entity.find('zenith.erp.india.Gstr2bRecord')
        .condition('supplierGstin', inv.supplierGstin)
        .condition('invoiceNumber', inv.vendorInvoiceNumber).disableAuthz().list()
    boolean isM = m2b ? true : false
    if (isM) matched++ else unmatched++
    rows.add([invoiceId: inv.invoiceId, vendorName: inv.fromPartyId, invoiceNumber: inv.vendorInvoiceNumber,
              invoiceDate: inv.invoiceDate, taxableValue: taxable, igst: iIgst, cgst: iCgst, sgst: iSgst,
              cess: BD(0), matched: isM])
}
totalInvoices = invoices.size()
totalTaxableValue = tTaxable; totalIgst = tIgst; totalCgst = tCgst; totalSgst = tSgst; totalCess = tCess
matchedCount = matched; unmatchedCount = unmatched; reportData = rows

def BD = { v -> (v ?: 0) as java.math.BigDecimal }
def half = { v -> BD(v).divide(new java.math.BigDecimal('2'), 2, java.math.RoundingMode.HALF_UP) }
def stateOf = { g -> (g && g.toString().length() >= 2) ? g.toString().substring(0,2) : null }
int y = Integer.parseInt(returnPeriod.substring(2)); int m = Integer.parseInt(returnPeriod.substring(0,2))
def fromTs = new java.sql.Timestamp(java.sql.Date.valueOf(java.time.LocalDate.of(y, m, 1)).time)
def toTs = new java.sql.Timestamp(java.sql.Date.valueOf(java.time.LocalDate.of(y, m, 1).plusMonths(1)).time)

def selfGstin = ec.entity.find('zenith.erp.india.IndiaGstin').condition('partyId', organizationPartyId).disableAuthz().one()
def supState = selfGstin ? (selfGstin.stateCode ?: stateOf(selfGstin.gstin)) : null

// Aggregate charged tax over a set of invoices; direction: 'out' uses buyerGstin state, 'in' uses supplierGstin state.
def agg = { typeList, orgField, counterpartyGstinField ->
    def res = [taxable: BD(0), cgst: BD(0), sgst: BD(0), igst: BD(0)]
    def list = ec.entity.find('mantle.account.invoice.Invoice')
        .condition(orgField, organizationPartyId)
        .condition('invoiceTypeEnumId', 'in', typeList)
        .condition('invoiceDate', '>=', fromTs).condition('invoiceDate', '<', toTs)
        .condition('statusId', org.moqui.entity.EntityCondition.NOT_IN, typeList.contains('InvoiceSales') ? ['InvoiceCancelled','InvoiceInProcess'] : ['InvoiceCancelled']).disableAuthz().list()
    list.each { inv ->
        boolean isReturn = inv.invoiceTypeEnumId?.toString()?.contains('Return')
        def sign = isReturn ? BD(-1) : BD(1)
        def taxable = BD(inv.totalTaxableAmount)
        def charged = inv.salesTotalsPreTax == 'Y' ?
            ec.service.sync().name('zenith.sales.SalesLineServices.calculate#InvoiceDisplayAmounts').parameters([invoice:inv.getMap()]).call().chargedTaxAmount : BD(inv.invoiceTotal) - taxable
        if (charged.signum() < 0) charged = BD(0)
        def cpState = stateOf(inv.get(counterpartyGstinField))
        boolean inter = (cpState != null && supState != null && cpState != supState) || (inv.isImportPurchase == 'Y')
        res.taxable += taxable * sign
        if (inter) { res.igst += charged * sign }
        else { def c = half(charged); res.cgst += c * sign; res.sgst += (charged - c) * sign }
    }
    return res
}

// 3.1 outward = sales invoices (POS sales already create linked InvoiceSales, so no double count).
def out = agg(['InvoiceSales','InvoiceSalesReturn','InvoiceSalesDebit'], 'fromPartyId', 'buyerGstin')
// 4 ITC = purchase invoices.
def itc = agg(['InvoicePurchase','InvoicePurchaseReturn'], 'toPartyId', 'supplierGstin')

table31 = [taxableValue: out.taxable, igst: out.igst, cgst: out.cgst, sgst: out.sgst, cess: BD(0)]
table32 = [igst: BD(0), cgst: BD(0), sgst: BD(0), cess: BD(0)]
table4 = [igst: itc.igst, cgst: itc.cgst, sgst: itc.sgst, cess: BD(0)]
table5 = [interState: BD(0), intraState: BD(0)]
netTaxPayable = [igst: out.igst - itc.igst, cgst: out.cgst - itc.cgst, sgst: out.sgst - itc.sgst, cess: BD(0)]

int matched = 0, unmatched = 0, missingInBooks = 0
String fileContent = ""
if (gstr2bJsonFile) {
    try { fileContent = new String(gstr2bJsonFile.get(), "UTF-8") }
    catch (Exception e) { fileContent = "" }
}
if (!fileContent) {
    ec.message.addMessage("No file uploaded or file is empty. Please upload a valid GSTR-2B JSON.", "warning")
    matchedCount = 0; unmatchedCount = 0; missingInBooksCount = 0
    return
}
try {
    def jsonSlurper = new groovy.json.JsonSlurper()
    def gstr2b = jsonSlurper.parseText(fileContent)
    def b2b = gstr2b?.data?.docdata?.b2b ?: gstr2b?.b2b ?: []
    for (supplier in b2b) {
        String supplierGstin = supplier.ctin ?: supplier.gstin ?: ""
        def invoices = supplier.inv ?: []
        for (inv in invoices) {
            String invNum = inv.inum ?: inv.val?.toString() ?: ""
            BigDecimal taxable = (inv.val ?: 0) as BigDecimal
            BigDecimal igst = 0, cgst = 0, sgst = 0
            for (item in (inv.items ?: inv.itms ?: [])) {
                def det = item.itm_det ?: item
                igst += (det.iamt ?: 0) as BigDecimal
                cgst += (det.camt ?: 0) as BigDecimal
                sgst += (det.samt ?: 0) as BigDecimal
                taxable = (det.txval ?: taxable) as BigDecimal
            }
            def existing = ec.entity.find("zenith.erp.india.Gstr2bRecord")
                .condition("supplierGstin", supplierGstin)
                .condition("invoiceNumber", invNum).one()
            if (!existing) {
                ec.entity.makeValue("zenith.erp.india.Gstr2bRecord").setAll([
                    supplierGstin:supplierGstin, invoiceNumber:invNum,
                    taxableAmount:taxable, igstAmount:igst, cgstAmount:cgst, sgstAmount:sgst,
                    returnPeriod:returnPeriod, matchStatus:"MissingInBooks"
                ]).setSequencedIdPrimary().create()
                missingInBooks++
            } else {
                if (existing.matchStatus == "Matched") matched++
                else unmatched++
            }
        }
    }
} catch (Exception e) {
    ec.message.addError("Error parsing GSTR-2B JSON: " + e.message)
}
matchedCount = matched; unmatchedCount = unmatched; missingInBooksCount = missingInBooks
ec.message.addMessage("GSTR-2B reconciliation complete: ${matched} matched, ${unmatched} unmatched, ${missingInBooks} missing in books.", "success")
